WITH fixes(pos,why) AS (VALUES (1,'Correto. O art. 71 da Constituição atribui ao Congresso Nacional o controle externo federal, exercido com auxílio do TCU. Auxiliar não significa substituir o Congresso.'),(5,'Correto. Nos arts. 70 e 71 da Constituição, o controle externo federal cabe ao Congresso Nacional, com auxílio do Tribunal de Contas da União.'),(6,'Correto. O art. 74 da Constituição determina que os Poderes mantenham, de forma integrada, sistema de controle interno para suas finalidades constitucionais.'),(7,'Correto. O art. 70 da Constituição inclui legalidade, legitimidade e economicidade entre os aspectos da fiscalização contábil, financeira e orçamentária.'),(9,'Correto. O art. 71, I, da Constituição prevê que o TCU aprecie as contas anuais do Presidente da República mediante parecer prévio, sem julgá-las definitivamente.'),(11,'Correto. O art. 71, II, da Constituição atribui ao TCU o julgamento das contas de administradores e demais responsáveis por recursos públicos.'),(12,'Correto. O art. 71, IV, da Constituição permite ao TCU realizar inspeções e auditorias por iniciativa própria, além de outras hipóteses previstas.'),(15,'Correto. A ação popular do art. 5º, LXXIII, da Constituição permite ao cidadão pedir anulação de ato lesivo ao patrimônio público e a outros bens tutelados.'),(16,'Correto. O art. 5º, LXXIII, da Constituição confere a qualquer cidadão legitimidade para propor ação popular; atenção à exigência de cidadania.'),(17,'Correto. O art. 129, III, da Constituição prevê como função institucional do Ministério Público promover inquérito civil e ação civil pública.'),(18,'Correto. O art. 74, IV, da Constituição determina que o controle interno apoie o controle externo no exercício de sua missão institucional.'),(19,'Correto. Pelo art. 74, § 1º, da Constituição, responsáveis pelo controle interno devem informar ao TCU irregularidades ou ilegalidades conhecidas, sob pena de responsabilidade solidária.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.pos=e.ordinality WHERE sm.slug='administrativo-controle-da-administracao-publica' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;